{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <meta name="description" content="About {{BUSINESS_NAME}} — practical outcomes, simple habits, and tactical frameworks for sustained wellbeing.">
  <style>
    :root{--glass:#ffffff11;--accent:#6dd3b2;--muted:#dfe7ec;--text:#062a2a;--glass-strong:#ffffff22}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,Arial,sans-serif;color:var(--text);background:#e7f2f0 url('assets/img/pattern.svg');-webkit-font-smoothing:antialiased}
    .nav{display:flex;justify-content:space-between;align-items:center;padding:18px 28px;background:linear-gradient(90deg,rgba(255,255,255,0.06),rgba(255,255,255,0.02));backdrop-filter:blur(8px);border-bottom:1px solid rgba(255,255,255,0.06)}
    .nav .brand{font-weight:700;letter-spacing:0.4px}
    .nav a{color:inherit;text-decoration:none;margin-left:16px;font-size:14px}
    .nav .links{display:flex;align-items:center}
    .container{max-width:1100px;margin:36px auto;padding:28px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
    .card{background:linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02));border-radius:14px;padding:22px;box-shadow:0 6px 22px rgba(7,20,20,0.06);backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,0.06)}
    h1{margin:0 0 8px 0;font-size:28px}
    p.lead{margin:0 0 18px 0;color:#0b3b36}
    .cta{display:inline-block;padding:10px 16px;border-radius:10px;background:var(--accent);color:white;text-decoration:none;font-weight:600}
    .process{display:flex;gap:14px;margin-top:24px}
    .step{flex:1;padding:14px;border-radius:10px;background:linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));border:1px solid rgba(255,255,255,0.04)}
    .step h4{margin:0 0 6px 0}
    .benefits{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:26px}
    .benefit{padding:14px;border-radius:10px}
    .proof-wrap{margin-top:28px}
    .proof{display:flex;gap:12px;align-items:center}
    .testimonial{flex:1;padding:14px;border-radius:10px;background:linear-gradient(180deg,#ffffff11,#ffffff06);border:1px solid rgba(255,255,255,0.04)}
    .badges{display:flex;gap:8px}
    .badge{display:inline-flex;align-items:center;gap:8px;padding:6px 8px;border-radius:8px;background:rgba(255,255,255,0.04);cursor:default;position:relative}
    .badge svg{width:16px;height:16px}
    .badge .tip{position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);background:#0b3b36;color:white;padding:6px 8px;border-radius:6px;font-size:12px;white-space:nowrap;display:none}
    .badge:hover .tip{display:block}
    .controls{display:flex;gap:8px;align-items:center;margin-left:8px}
    .dot{width:10px;height:10px;border-radius:50%;background:rgba(255,255,255,0.18);cursor:pointer}
    .dot.active{background:var(--accent)}
    footer{margin-top:36px;text-align:center;color:#0b3b36aa}
    /* small screens */
    @media(max-width:880px){.hero{grid-template-columns:1fr;}.benefits{grid-template-columns:1fr}.nav{padding:14px}.container{margin:16px}}
  </style>
</head>
<body>
  <nav class="nav">
    <div class="brand">{{BUSINESS_NAME}}</div>
    <div class="links">
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Programs</a>
      <a href="pricing.html">Invest</a>
      <a href="testimonials.html">Stories</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </div>
  </nav>

  <main class="container">
    <section class="hero card">
      <div>
        <h1>Practical frameworks for steady progress</h1>
        <p class="lead">I help professionals translate intentions into small, repeatable habits that create measurable wellbeing shifts without overhauling schedules.</p>
        <p style="margin:0 0 12px 0;color:#08433f;font-weight:600">Offer model: VIP Day & targeted packages</p>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <div class="process" aria-hidden="true">
          <div class="step"><h4>Map</h4><p>Clarify current rhythms and priorities.</p></div>
          <div class="step"><h4>Prototype</h4><p>Test tiny adjustments that stack.</p></div>
          <div class="step"><h4>Anchor</h4><p>Install habits into real-world routines.</p></div>
        </div>
      </div>
      <aside>
        <div class="card">
          <h4>Quick snapshot</h4>
          <p style="margin:8px 0 12px 0">Bespoke VIP Day intensives for owners and leaders: one focused day to build a sustainable weekly plan.</p>
          <p style="font-weight:700;margin:0">Reach: <span style="color:var(--accent)">{{CITY}}, {{STATE}}</span></p>
        </div>
        <div style="height:12px"></div>
        <div class="card">
          <h4>Connect</h4>
          <p style="margin:8px 0">Call: <a href="tel:{{PHONE}}">{{PHONE}}</a><br>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
      </aside>
    </section>

    <section class="card" style="margin-top:22px">
      <h3 style="margin:0 0 10px 0">How work unfolds</h3>
      <ol style="margin:0 0 0 18px;padding:0;color:#08322f">
        <li style="margin:8px 0">Pre-session intake and habit audit</li>
        <li style="margin:8px 0">Intensive strategy session (VIP Day option available)</li>
        <li style="margin:8px 0">Two-week rapid-cycle prototyping and check-in</li>
        <li style="margin:8px 0">Hand-off toolkit and sustainable plan</li>
      </ol>
    </section>

    <section class="card benefits" aria-labelledby="benefits-heading">
      <div class="benefit">
        <h4>Outcome-oriented</h4>
        <p>Clear milestones and review points — not vague goals.</p>
      </div>
      <div class="benefit">
        <h4>Habit-first</h4>
        <p>Micro-practices built into days you already have.</p>
      </div>
      <div class="benefit">
        <h4>Frameworks</h4>
        <p>Reproducible templates you can apply across weeks.</p>
      </div>
    </section>

    <section class="card proof-wrap">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <h3 style="margin:0">Proof gallery</h3>
        <div class="badges">
          <div class="badge" data-tip="Published by Human Work Journal">
            <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10" stroke="#fff" stroke-opacity="0.6"/></svg>
            <div class="tip">Human Work Journal</div>
            <div style="font-size:13px">Press</div>
          </div>
          <div class="badge" data-tip="Featured on The Career Reset">
            <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="3" width="18" height="18" rx="4" stroke="#fff" stroke-opacity="0.6"/></svg>
            <div class="tip">The Career Reset</div>
            <div style="font-size:13px">Media</div>
          </div>
          <div class="badge" data-tip="Endorsed by industry coaches">
            <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15 8H21L16.5 12L18.5 18L12 14.5L5.5 18L7.5 12L3 8H9L12 2Z" stroke="#fff" stroke-opacity="0.6"/></svg>
            <div class="tip">Peer Endorsement</div>
            <div style="font-size:13px">Cred</div>
          </div>
        </div>
      </div>

      <div style="display:flex;gap:12px;margin-top:12px;align-items:flex-start">
        <div class="testimonial card" id="testimonial">
          <p id="test-text" style="margin:0 0 8px 0;font-style:italic">"This session turned a scattered plan into the clearest small steps I've taken — all doable in a busy week."</p>
          <p style="margin:0;font-weight:700" id="test-author">— Alex M., Founder</p>
        </div>
        <div style="display:flex;flex-direction:column;align-items:flex-start">
          <div style="display:flex;gap:8px;align-items:center">
            <div class="controls" id="controls"></div>
          </div>
          <small style="color:#0b3b36aa;margin-top:10px">Testimonials rotate automatically. Hover badges to read provenance.</small>
        </div>
      </div>
    </section>

    <section class="card" style="margin-top:18px;display:flex;justify-content:space-between;align-items:center">
      <div>
        <h3 style="margin:0">Ready for a focused day?</h3>
        <p style="margin:6px 0">Book a VIP Day to walk away with a ready-to-run weekly plan and a two-week prototyping schedule.</p>
      </div>
      <div>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">Reserve a Day</a>
      </div>
    </section>

    <footer>
      <small>Located in {{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></small>
    </footer>
  </main>

  <script>
    (function(){
      // Proof gallery data
      const items = [
        {text: '"Precision and small experiments changed how I approach busy weeks. Worth the investment."', author: '— Priya S., Operations Lead'},
        {text: '"We used the VIP Day to map energy and workload — the plan stuck because it fit real days."', author: '— Marco T., CEO'},
        {text: '"Practical and direct: the habit prescriptions were doable and measurable."', author: '— Leah P., Consultant'}
      ];
      let idx = 0;
      const textEl = document.getElementById('test-text');
      const authorEl = document.getElementById('test-author');
      const controls = document.getElementById('controls');

      function show(i){
        idx = i % items.length;
        // simple fade
        textEl.style.opacity = 0;
        authorEl.style.opacity = 0;
        setTimeout(()=>{
          textEl.textContent = items[idx].text;
          authorEl.textContent = items[idx].author;
          textEl.style.opacity = 1;
          authorEl.style.opacity = 1;
        },220);
        // dots
        Array.from(controls.children).forEach((d,di)=>d.classList.toggle('active',di===idx));
      }

      // build dots
      items.forEach((it,i)=>{
        const dot = document.createElement('div');
        dot.className='dot'+(i===0? ' active':'');
        dot.addEventListener('click',()=>{ pauseAuto(); show(i); });
        controls.appendChild(dot);
      });

      let auto = setInterval(()=>{ idx = (idx+1)%items.length; show(idx); },5000);
      function pauseAuto(){ clearInterval(auto); auto = null; }

      // pause on hover
      const wrap = document.querySelector('.proof-wrap');
      wrap.addEventListener('mouseenter', ()=>{ if(auto) pauseAuto(); });
      wrap.addEventListener('mouseleave', ()=>{ if(!auto) auto = setInterval(()=>{ idx = (idx+1)%items.length; show(idx); },5000); });

      // initial show
      show(0);
    })();
  </script>
</body>
</html>"} 
{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Services: focused sessions, package support, and VIP Day options for busy professionals.">
  <style>
    :root{--accent:#e28f7a;--glass:#ffffff10;--bg:#f6f8f7;--text:#082a28}
    html,body{margin:0;font-family:Inter,system-ui,Arial,sans-serif;color:var(--text);background:var(--bg) url('assets/img/pattern.svg')}
    .nav{display:flex;justify-content:space-between;align-items:center;padding:14px 22px;background:linear-gradient(180deg,rgba(255,255,255,0.04),rgba(255,255,255,0.01));backdrop-filter:blur(8px)}
    .nav a{margin-left:14px;text-decoration:none;color:inherit}
    .wrap{max-width:1100px;margin:30px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.06),rgba(255,255,255,0.02));padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.04);backdrop-filter:blur(8px)}
    h1{margin:0 0 8px 0}
    .services-list{display:flex;flex-direction:column;gap:12px}
    .service{display:flex;justify-content:space-between;align-items:center;padding:12px;border-radius:10px;background:rgba(255,255,255,0.02)}
