</head>
<body>
  <nav class="nav">
    <div class="brand">{{BUSINESS_NAME}}</div>
    <div class="links">
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Programs</a>
      <a href="pricing.html">Invest</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </div>
  </nav>

  <main class="wrap">
    <section class="intro">
      <div class="card">
        <h1 style="margin:0">Programs</h1>
        <p style="margin:8px 0 0 0">Structured multi-week experiences to embed practices and measure outcomes. Each program includes tracked checkpoints and a closing planning session.</p>
      </div>

      <div class="card" style="min-width:260px">
        <h4 style="margin:0 0 10px 0">Compare pricing</h4>
        <div class="toggle">
          <span>Monthly</span>
          <div id="switch2" class="switch" role="button" aria-pressed="false">
            <div class="knob"></div>
          </div>
          <span>Package</span>
        </div>
        <p class="small" style="margin:10px 0 0 0">Toggle to animate amount changes between monthly rate and whole-program investment.</p>
      </div>
    </section>

    <section class="programs">
      <div class="card prog">
        <h4>Foundations Track</h4>
        <p style="margin:6px 0">Eight-week program for habit groundwork and systems that simplify weekly choices.</p>
        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:12px">
          <div class="small">Includes two coaching calls per month</div>
          <div class="price" data-month="125" data-package="900">$125</div>
        </div>
        <div style="margin-top:12px"><a href="{{PRIMARY_CTA_URL}}" style="padding:8px 12px;border-radius:8px;background:var(--accent);color:white;text-decoration:none;font-weight:700">Join Foundations</a></div>
