  <script>
    (function(){
      const sw = document.getElementById('switch2');
      const prices = Array.from(document.querySelectorAll('.price'));
      let mode = 'month';

      function animateNumber(el, from, to){
        const duration = 500;
        const start = performance.now();
        function step(now){
          const t = Math.min(1,(now-start)/duration);
          const val = Math.round(from + (to-from)*t);
          el.textContent = (val>=1000? '$' + val.toLocaleString() : '$' + val);
          if(t<1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      function update(toMode){
        prices.forEach(p=>{
          const m = Number(p.getAttribute('data-month'));
          const pkg = Number(p.getAttribute('data-package'));
          const current = parseInt(p.textContent.replace(/[^0-9]/g,''),10);
          const target = toMode==='package'? pkg : m;
          animateNumber(p, current, target);
        });
      }

      sw.addEventListener('click', ()=>{
        const on = sw.classList.toggle('on');
        sw.setAttribute('aria-pressed', on? 'true':'false');
        mode = on? 'package':'month';
        update(mode);
      });

      // init
      prices.forEach(p=>{
        p.textContent = '$' + p.getAttribute('data-month');
      });
    })();
  </script>
